SourceCode.Declaration:
/// <summary>
/// PricingAttribute of table <c>InventTable</c> field ItemId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
[UPSPricingAttributeFieldsDiscovery(fieldStr(InventTable, ItemId))]
internal class UPSPricingAttributeInventTableItemId extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, ItemId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTable inventTable;
    EcoResProductTranslation ecoResProductTranslation;

    while select ItemId from inventTable
        outer join Name from ecoResProductTranslation
        group by inventTable.ItemId, ecoResProductTranslation.Name
        where inventTable.Product == ecoResProductTranslation.Product
            && ecoResProductTranslation.LanguageId == 'en-us'
    {
        UPSPricingAttributeAllowedValuesObject valueObject = 
            new UPSPricingAttributeAllowedValuesObject(inventTable.ItemId, ecoResProductTranslation.Name);
        ret.add(valueObject);
    }
    return ret;
}
